<?php
require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();oecrm_require_permission($conn,'payroll','export');$companyId=oecrm_current_company_id($conn);$runId=oecrm_int_param($_GET,'run_id');$stmt=mysqli_prepare($conn,'SELECT * FROM payroll_runs WHERE id=? AND company_id=?');mysqli_stmt_bind_param($stmt,'ii',$runId,$companyId);mysqli_stmt_execute($stmt);$run=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$run){http_response_code(404);exit('Payroll run not found.');}$rows=mysqli_query($conn,'SELECT e.employeeCode,e.name,e.designation,p.* FROM payroll_items p JOIN employeestbl e ON e.id=p.employee_id WHERE p.payroll_run_id='.(int)$runId.' ORDER BY e.name');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="payroll-summary-'.$run['period_year'].'-'.sprintf('%02d',$run['period_month']).'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Employee Code','Employee','Designation','Present Days','Paid Leave','Unpaid Leave','Effective Minutes','Gross Salary','Attendance Deduction','Leave Deduction','Professional Tax','Retention','Other Deduction','Total Deduction','Net Salary']);while($r=mysqli_fetch_assoc($rows)){fputcsv($out,[$r['employeeCode'],$r['name'],$r['designation'],$r['present_days'],$r['paid_leave_days'],$r['unpaid_leave_days'],$r['effective_minutes'],$r['gross_salary'],$r['attendance_deduction'],$r['leave_deduction'],$r['professional_tax'],$r['retention_amount'],$r['custom_deduction'],$r['total_deduction'],$r['net_salary']]);}fclose($out);oecrm_audit($conn,'payroll','summary_export','payroll_run',$runId,'Payroll summary exported');exit;